// İki giriş de buradan geçer:
//  • Webhook ile gelen istekte alanlar "body" içindedir,
//  • Workflow 05'in /abonelik komutunda alanlar doğrudan gelir.
// Sözdizimi Telegram ile aynı: {"metin": "ekle Netflix 229,99 15"}
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body');
const govde = webhooktan ? (j.body && typeof j.body === 'object' ? j.body : {}) : j;

const chat_id = govde.chat_id ? String(govde.chat_id) : '';
const ISLEMLER = { liste: 'liste', ekle: 'ekle', sil: 'sil' };
const metin = String(govde.metin || '').trim();
const ilk = metin.split(/\s+/)[0].toLowerCase();
let islem = 'liste';
let arg = '';
if (metin) {
  islem = ISLEMLER[ilk] || 'bilinmeyen';
  arg = ISLEMLER[ilk] ? metin.slice(ilk.length).trim() : metin;
}

return [{ json: { islem, arg, chat_id, webhooktan } }];

// ── Ortak: sıradaki ödeme tarihi ve biçimlendirme ───────────────────────────
// Tarihler yerel saatle (GENERIC_TIMEZONE). "gun: 31" olan ödeme kısa ayda
// ayın son gününe çekilir — hiçbir ay atlanmaz.
const iki = (n) => String(n).padStart(2, '0');
const anahtar = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1) + '-' + iki(d.getDate());
const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' TL';
const bugun = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; })();

const aboneligiDuzenle = (a) => ({
  ...a,
  id: Number(a.id) || 0,
  ad: String(a.ad || '').trim(),
  tutar: typeof a.tutar === 'number' ? a.tutar : null,
  periyot: a.periyot === 'yillik' ? 'yillik' : 'aylik',
  gun: Math.min(31, Math.max(1, Number(a.gun) || 1)),
  ay: a.periyot === 'yillik' ? Math.min(12, Math.max(1, Number(a.ay) || 1)) : null,
  onceden: Number.isFinite(Number(a.onceden)) && a.onceden !== null ? Math.max(0, Number(a.onceden)) : 3,
  aktif: a.aktif !== false,
  sonHatirlatilan: a.sonHatirlatilan || null,
});

const sonrakiOdeme = (a) => {
  const gunIcin = (yil, ay) => new Date(yil, ay, Math.min(a.gun, new Date(yil, ay + 1, 0).getDate()));
  const y = bugun.getFullYear();
  if (a.periyot === 'yillik') {
    let d = gunIcin(y, a.ay - 1);
    if (d < bugun) d = gunIcin(y + 1, a.ay - 1);
    return d;
  }
  let d = gunIcin(y, bugun.getMonth());
  if (d < bugun) d = gunIcin(y, bugun.getMonth() + 1);
  return d;
};
const kalanGun = (d) => Math.round((d.getTime() - bugun.getTime()) / 86400000);
const neZaman = (n) => (n === 0 ? 'bugün' : n === 1 ? 'yarın' : n + ' gün sonra');
const tarihMetni = (d) => d.toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });
const periyotMetni = (a) => (a.periyot === 'yillik'
  ? 'her yıl ' + tarihMetni(new Date(2000, a.ay - 1, a.gun))
  : 'her ayın ' + a.gun + '. günü');
const aylikYuk = (liste) => liste
  .filter((a) => a.aktif && typeof a.tutar === 'number')
  .reduce((t, a) => t + (a.periyot === 'yillik' ? a.tutar / 12 : a.tutar), 0);
// ─────────────────────────────────────────────────────────────────────────────
// Liste / ekle / sil. Dosya bozuksa durur — aksi hâlde liste boş sanılıp
// üzerine yazılır ve tüm ödeme tanımları kaybolur.
const okuHata = $('Abonelikleri Oku').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Abonelikleri Çıkar').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('abonelikler.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}

const istek = $('İsteği Al (Abonelik)').first().json;
const okunan = dosyaYok ? {} : ($input.first().json || {});
const veri = okunan.data || okunan;
const abonelikler = (Array.isArray(veri.abonelikler) ? veri.abonelikler : [])
  .filter((a) => a && a.ad)
  .map(aboneligiDuzenle);

// "149,90" · "1.250" · "15000" → sayı
const sayiyaCevir = (ham) => {
  let t = String(ham).trim();
  const sonNokta = t.lastIndexOf('.');
  const sonVirgul = t.lastIndexOf(',');
  if (sonVirgul > sonNokta) t = t.replace(/\./g, '').replace(',', '.');
  else if (sonVirgul === -1 && /^\d{1,3}(\.\d{3})+$/.test(t)) t = t.replace(/\./g, '');
  else t = t.replace(/,/g, '');
  const n = Number(t);
  return /^[0-9.]+$/.test(t) && Number.isFinite(n) ? n : null;
};

// "Netflix 229,99 15" · "Kira 15.000 TL aylik 1" · "Alan adı 450 yillik 14.03"
// Sondan çözülür, böylece adın içinde sayı olabilir ("Netflix 4K 229 15").
const ekleCoz = (metin) => {
  const t = metin.split(/\s+/).filter((x) => !/^(tl|₺|try)$/i.test(x));
  if (t.length < 3) return null;
  let periyot = 'aylik';
  let gun;
  let ay = null;
  const son = t.pop();
  const tarih = son.match(/^(\d{1,2})[./](\d{1,2})$/);
  if (tarih) {
    periyot = 'yillik';
    gun = Number(tarih[1]);
    ay = Number(tarih[2]);
    if (/^(yillik|yıllık|yilda|yılda)$/i.test(t[t.length - 1] || '')) t.pop();
  } else if (/^\d{1,2}$/.test(son)) {
    gun = Number(son);
    if (/^(aylik|aylık|ayda)$/i.test(t[t.length - 1] || '')) t.pop();
  } else {
    return null;
  }
  const tutar = sayiyaCevir(t.pop() || '');
  const ad = t.join(' ').trim();
  if (!ad || tutar === null || tutar <= 0 || gun < 1 || gun > 31 || (ay !== null && (ay < 1 || ay > 12))) return null;
  return { ad: ad.slice(0, 60), tutar, periyot, gun, ay };
};

const liste = () => {
  const aktif = abonelikler.filter((a) => a.aktif);
  if (aktif.length === 0) return 'Düzenli ödeme yok.\nEklemek için: /abonelik ekle Netflix 229,99 15';
  const yuk = aylikYuk(aktif);
  const satirlar = aktif
    .map((a) => ({ a, d: sonrakiOdeme(a) }))
    .sort((x, y) => x.d - y.d)
    .map(({ a, d }) => {
      const n = kalanGun(d);
      return (n <= a.onceden ? '⏰' : '•') + ' #' + a.id + ' ' + a.ad + ' — ' +
        (a.tutar !== null ? tl(a.tutar) : '?') + ' · ' + periyotMetni(a) + ' → ' + neZaman(n) +
        (n > 1 ? ' (' + tarihMetni(d) + ')' : '');
    });
  return '💳 Düzenli ödemeler — aylık yük ' + tl(Math.round(yuk)) + ' (yıllık ' + tl(Math.round(yuk * 12)) + ')\n' +
    satirlar.join('\n');
};

let mesaj = '';
let yazilsin = false;
let hata = false;

if (istek.islem === 'liste') {
  mesaj = liste();
} else if (istek.islem === 'ekle') {
  const c = ekleCoz(istek.arg);
  if (!c) {
    hata = true;
    mesaj = [
      'Kullanım:',
      '• /abonelik ekle Netflix 229,99 15        → her ayın 15\'i',
      '• /abonelik ekle Alan adı 450 yillik 14.03 → her yıl 14 Mart',
    ].join('\n');
  } else {
    const id = abonelikler.reduce((mx, a) => Math.max(mx, a.id), 0) + 1;
    const yeni = aboneligiDuzenle({ id, ...c, paraBirimi: 'TL', onceden: 3, olusturulma: new Date().toISOString() });
    abonelikler.push(yeni);
    yazilsin = true;
    const d = sonrakiOdeme(yeni);
    mesaj = '➕ Eklendi: #' + id + ' ' + yeni.ad + ' — ' + tl(yeni.tutar) + ' · ' + periyotMetni(yeni) +
      '\nSıradaki ödeme: ' + tarihMetni(d) + ' (' + neZaman(kalanGun(d)) + '). ' + yeni.onceden + ' gün önceden hatırlatırım.';
  }
} else if (istek.islem === 'sil') {
  const id = Number((istek.arg.match(/#?(\d+)/) || [])[1]) || 0;
  const a = abonelikler.find((x) => x.id === id);
  if (!a) {
    hata = true;
    mesaj = (id ? '#' + id + ' bulunamadı.' : 'Kullanım: /abonelik sil 3') + '\n\n' + liste();
  } else {
    abonelikler.splice(abonelikler.indexOf(a), 1);
    yazilsin = true;
    mesaj = '🗑 Silindi: #' + a.id + ' ' + a.ad;
  }
} else {
  hata = true;
  mesaj = [
    'Düzenli ödeme komutları:',
    '• /abonelik → liste ve aylık yük',
    '• /abonelik ekle Netflix 229,99 15',
    '• /abonelik ekle Alan adı 450 yillik 14.03',
    '• /abonelik sil 3',
  ].join('\n');
}

const sonuc = abonelikler.map((a) => {
  const d = sonrakiOdeme(a);
  return { id: a.id, ad: a.ad, tutar: a.tutar, periyot: a.periyot, gun: a.gun, ay: a.ay,
           aktif: a.aktif, sonrakiOdeme: anahtar(d), kalanGun: kalanGun(d) };
});

return [{
  json: {
    islem: istek.islem, chat_id: istek.chat_id, webhooktan: istek.webhooktan,
    mesaj, hata, sonuc, aylikYuk: Math.round(aylikYuk(abonelikler) * 100) / 100, yazilsin, abonelikler,
  },
}];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// İstek Telegram'dan geldiyse sonuç oraya gider.
const j = $input.first().json;
if (!j.chat_id) return [];
return [{ json: { chat_id: j.chat_id, text: String(j.mesaj).slice(0, 3900) } }];

// Dosyaya yalnızca ödeme listesi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { abonelikler: j.abonelikler } }];

// ── Ortak: sıradaki ödeme tarihi ve biçimlendirme ───────────────────────────
// Tarihler yerel saatle (GENERIC_TIMEZONE). "gun: 31" olan ödeme kısa ayda
// ayın son gününe çekilir — hiçbir ay atlanmaz.
const iki = (n) => String(n).padStart(2, '0');
const anahtar = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1) + '-' + iki(d.getDate());
const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' TL';
const bugun = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; })();

const aboneligiDuzenle = (a) => ({
  ...a,
  id: Number(a.id) || 0,
  ad: String(a.ad || '').trim(),
  tutar: typeof a.tutar === 'number' ? a.tutar : null,
  periyot: a.periyot === 'yillik' ? 'yillik' : 'aylik',
  gun: Math.min(31, Math.max(1, Number(a.gun) || 1)),
  ay: a.periyot === 'yillik' ? Math.min(12, Math.max(1, Number(a.ay) || 1)) : null,
  onceden: Number.isFinite(Number(a.onceden)) && a.onceden !== null ? Math.max(0, Number(a.onceden)) : 3,
  aktif: a.aktif !== false,
  sonHatirlatilan: a.sonHatirlatilan || null,
});

const sonrakiOdeme = (a) => {
  const gunIcin = (yil, ay) => new Date(yil, ay, Math.min(a.gun, new Date(yil, ay + 1, 0).getDate()));
  const y = bugun.getFullYear();
  if (a.periyot === 'yillik') {
    let d = gunIcin(y, a.ay - 1);
    if (d < bugun) d = gunIcin(y + 1, a.ay - 1);
    return d;
  }
  let d = gunIcin(y, bugun.getMonth());
  if (d < bugun) d = gunIcin(y, bugun.getMonth() + 1);
  return d;
};
const kalanGun = (d) => Math.round((d.getTime() - bugun.getTime()) / 86400000);
const neZaman = (n) => (n === 0 ? 'bugün' : n === 1 ? 'yarın' : n + ' gün sonra');
const tarihMetni = (d) => d.toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });
const periyotMetni = (a) => (a.periyot === 'yillik'
  ? 'her yıl ' + tarihMetni(new Date(2000, a.ay - 1, a.gun))
  : 'her ayın ' + a.gun + '. günü');
const aylikYuk = (liste) => liste
  .filter((a) => a.aktif && typeof a.tutar === 'number')
  .reduce((t, a) => t + (a.periyot === 'yillik' ? a.tutar / 12 : a.tutar), 0);
// ─────────────────────────────────────────────────────────────────────────────
// Sabah kontrolü: sıradaki ödemesine "onceden" gün ya da daha az kalanlar.
// Her ödeme tarihi için BİR KEZ hatırlatılır (sonHatirlatilan). "Elle Test Et"
// ile çalıştırılınca işaretlere bakılmaz, pencere içindeki her şey gösterilir.
const okuHata = $('Abonelikleri Oku (Sabah)').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Abonelikleri Çıkar (Sabah)').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('abonelikler.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}
if (dosyaYok) return [{ json: { gonderilecek: false, yazilsin: false } }];

let elle = false;
try { elle = $('Elle Test Et (Abonelik)').all().length > 0; } catch (e) { elle = false; }

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const okunan = $input.first().json || {};
const veri = okunan.data || okunan;
const abonelikler = (Array.isArray(veri.abonelikler) ? veri.abonelikler : [])
  .filter((a) => a && a.ad)
  .map(aboneligiDuzenle);

const yaklasan = [];
for (const a of abonelikler) {
  if (!a.aktif) continue;
  const d = sonrakiOdeme(a);
  const n = kalanGun(d);
  if (n > a.onceden) continue;
  if (!elle && a.sonHatirlatilan === anahtar(d)) continue;
  a.sonHatirlatilan = anahtar(d);
  yaklasan.push({ a, d, n });
}
if (yaklasan.length === 0) return [{ json: { gonderilecek: false, yazilsin: false } }];

yaklasan.sort((x, y) => x.n - y.n);
const toplam = yaklasan.reduce((t, x) => t + (x.a.tutar || 0), 0);
const satirlar = yaklasan.map(({ a, d, n }) =>
  (n === 0 ? '💳 Bugün: ' : '⏰ ' + neZaman(n).replace(/^./, (c) => c.toUpperCase()) + ' (' + tarihMetni(d) + '): ') +
  a.ad + ' — ' + (a.tutar !== null ? tl(a.tutar) : 'tutar yok'));
const text = '💳 Yaklaşan ödemeler\n' + satirlar.join('\n') +
  (yaklasan.length > 1 ? '\n\nToplam: ' + tl(toplam) : '') +
  '\nÖdedikten sonra kaydetmek için: /harcama <tutar> <açıklama>';

return [{
  json: {
    gonderilecek: true,
    yazilsin: true,
    text,
    konu: '💳 Yaklaşan ödeme: ' + yaklasan.map((x) => x.a.ad).join(', '),
    html: '<h3>💳 Yaklaşan ödemeler</h3><ul>' + satirlar.map((s) => '<li>' + esc(s) + '</li>').join('') + '</ul>',
    govde: { abonelikler },
  },
}];

// Telegram kuruluysa hatırlatma oraya gider; değilse bu dal boş döner.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE hatırlatma mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];

// Hatırlatılan ödeme tarihleri işaretlenir: aynı ödeme için ikinci kez yazılmaz.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: j.govde }];
